#define iterations 100
#define volsteps 26
#define stepsize 0.125
#define zoom 0.500
#define tile   0.850
#define speed  0.005 
#define brightness 0.0025
#define distfading 0.730
#define waveSpeed 0.1 
#define waveAmplitude 0.4 

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy / iResolution.xy - 0.5;
    uv.y *= iResolution.y / iResolution.x;
    vec3 dir = vec3(uv * zoom, 1.0);
    float time = iTime * speed + 0.25;

    vec3 from = vec3(1.0, 0.5, 0.5);
    from += vec3(time * 2.0, time, -2.0);
    from = mod(from, tile) - tile / 2.0;

    float s = 0.1, fade = 1.0;
    vec3 v = vec3(0.0);
    for (int r = 0; r < volsteps; r++) {
        vec3 p = from + s * dir * 0.5;

        float pa = 0.0, a = 0.0;
        for (int i = 0; i < iterations; i++) {
            p = abs(p) / dot(p, p) - .7;
            a += abs(p.x + p.y + p.z); 
            pa += exp(-abs(length(p) - 0.2) * 3.0); 
        }

        a *= a * a;          

        v += vec3(s, s*s, s*s*s*s) * a * (brightness * 0.5) * fade; 


        float wave = sin(time * waveSpeed + p.z * 5.0) * waveAmplitude;
        float waveInfluence = smoothstep(0.0, 1.0, abs(wave)); 
        vec3 waveColor = vec3(0.0, 0.5, 1.0); 
        v = mix(v, waveColor, waveInfluence * 0.2); 

        fade *= distfading; 
        s += stepsize;
    }

    v = v / float(volsteps); 
    v *= 0.9; 

    float vignette = 1.0 - smoothstep(0.0, 0.7, length(uv)); 
    v *= vignette; 

    fragColor = vec4(v * 0.01, 1.0);
}
